(1) operator!=



namespace rel_ops
{
    template<class T>
    bool operator!=(const T& lhs, const T& rhs)
    {
        return !(lhs == rhs);
    }
}


(2) operator>



namespace rel_ops
{
    template<class T>
    bool operator>(const T& lhs, const T& rhs)
    {
        return rhs < lhs;
    }
}


(3) operator<=



namespace rel_ops
{
    template<class T>
    bool operator<=(const T& lhs, const T& rhs)
    {
        return !(rhs < lhs);
    }
}


(4) operator>=



namespace rel_ops
{
    template<class T>
    bool operator>=(const T& lhs, const T& rhs)
    {
        return !(lhs < rhs);
    }
}

examples.code:
#include <iostream>
#include <utility>

struct Foo {
    int n;
};

bool operator==(const Foo &lhs, const Foo &rhs) { return lhs.n == rhs.n; }

bool operator<(const Foo &lhs, const Foo &rhs) { return lhs.n < rhs.n; }

int main() {
    Foo f1 = {1};
    Foo f2 = {2};
    using namespace std::rel_ops;

    std::cout << std::boolalpha << "{1} != {2} : " << (f1 != f2) << '\n'
              << "{1} >  {2} : " << (f1 > f2) << '\n'
              << "{1} <= {2} : " << (f1 <= f2) << '\n'
              << "{1} >= {2} : " << (f1 >= f2) << '\n';
}
